-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

-- Widening conversions inside an ORC union branch: the branch of a union column is read with a
-- per-branch type hint, because the final Variant -> Variant cast can only extend the set of
-- alternatives by exact type name, not widen one of them.

-- uniontype<int,string>, inferred.
SELECT toTypeName(u), u FROM format(ORC, unhex(''));

-- The int branch widened to Int64 and to Float64.
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Int64, String)', unhex(''));
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Float64, String)', unhex(''));

-- uniontype<float,string>: the float branch read as itself and widened to Float64.
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Float32, String)', unhex(''));
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Float64, String)', unhex(''));

-- The widening also applies inside a complex branch: uniontype<array<int>,string> as Array(Int64).
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Array(Int64), String)', unhex(''));

-- uniontype<tinyint,bigint>: both branches match Int64, so the exact-width pairing decides which
-- branch takes it, and the other one is widened.
SELECT toTypeName(u), u FROM format(ORC, unhex(''));
SET allow_suspicious_variant_types = 1;
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Int8, Int64)', unhex(''));
SELECT toTypeName(u), u FROM format(ORC, 'u Variant(Int64, Int128)', unhex(''));
